console.log(
  `\n\x1b[1m${passed} passed, ${failed} failed\x1b[0m` + (failed ? ` \x1b[31m(${failures.map((f) => f[0]).join(", ")})\x1b[0m` : "") + "\n",
);
process.exit(failed ? 1 : 0);
